def _validate_receipt_items(
    raw_lines: Sequence[str],
) -> tuple[list[tuple[int, ReceiptItemInput]], list[str]]:
    """Validate every ``批次号,实收数量`` receipt line.

    Received quantity is a non-negative integer (zero means the lot did not
    arrive). Returns (line number, item) pairs and per-line errors; callers
    must reject the whole receipt whenever the error list is non-empty.
    """
    parsed: list[tuple[int, ReceiptItemInput]] = []
    errors: list[str] = []
    seen_lots: dict[str, int] = {}

    for index, raw in enumerate(raw_lines, start=1):
        parts = [part.strip() for part in raw.split(",")]
        if len(parts) != 2:
            errors.append(
                f"实收行 {index}: 实收行格式错误，应为“批次号,实收数量”"
            )
            continue

        lot, quantity_raw = parts
        line_ok = True

        if not lot:
            errors.append(f"实收行 {index}: 批次号不能为空")
            line_ok = False

        if not quantity_raw.isdigit():
            errors.append(
                f"实收行 {index}: 实收数量 {quantity_raw!r} 必须为非负整数"
            )
            line_ok = False

        if not line_ok:
            continue

        item = ReceiptItemInput(lot, int(quantity_raw))
        parsed.append((index, item))
        first_line = seen_lots.get(lot)
        if first_line is None:
            seen_lots[lot] = index
        else:
            errors.append(
                f"实收行 {index}: 批次号 {lot} 与实收行 {first_line} 重复"
            )

    return parsed, errors

